{
  "id": "grid-frequency-stability-ene",
  "name": "Grid Frequency Stability Dynamics",
  "description": "Illustrative grid-frequency experiment with physically consistent rotating-energy balance. Power is MW, time seconds, frequency Hz and kinetic energy MW s. Initial stored energy is derived from the existing System Inertia (5 s) times Base Generation (1000 MW), rather than an independent inconsistent 100. The net Inertial Response is demand minus generation, allowing both kinetic discharge and recharge. Frequency Change follows the exact nonlinear swing-energy identity df/dt=(Pgen-Pload)*f/(2E), retaining E/(f/f0)^2=5000 MW s. Adaptive Radau preserves the kinetic invariant to relative error below 2e-11 over the full 60 s, keeps the original output step .01, and permits half/quarter output refinements within the work budget. All original elements, geometry, forcing, droop and reserve paths remain. Governor/droop/reserve dynamics are illustrative local assumptions; this is not a reproduction of the NREL virtual-synchronous-generator network.",
  "source": "https://docs.nlr.gov/docs/fy20osti/73872.pdf",
  "reference": "Yan et al. (2020), NREL/CP-5D00-73872, printed p.4 (PDF p.7), eq.(12): per-unit power imbalance equals 2 H omega times d omega/dt. SI mapping E=H*Sbase*(f/f0)^2 gives dE/dt=Pgen-Pload and df/dt=(Pgen-Pload)*f/(2E).",
  "stocks": [
    {
      "id": "stock-frequency",
      "name": "Grid Frequency",
      "initial_value": 60,
      "equation": "",
      "position": {
        "x": 300,
        "y": 200
      },
      "units": "Hz"
    },
    {
      "id": "stock-kinetic-energy",
      "name": "Stored Kinetic Energy",
      "initial_value": 100,
      "equation": "System_Inertia * Base_Generation",
      "position": {
        "x": 500,
        "y": 200
      },
      "units": "MW s"
    },
    {
      "id": "stock-reserve",
      "name": "Spinning Reserve",
      "initial_value": 500,
      "equation": "",
      "position": {
        "x": 300,
        "y": 400
      },
      "units": "MW"
    }
  ],
  "flows": [
    {
      "id": "flow-frequency-change",
      "name": "Frequency Change",
      "equation": "(Total_Generation - Total_Demand) * Grid_Frequency / (2 * Stored_Kinetic_Energy)",
      "from_stock": null,
      "to_stock": "stock-frequency",
      "position": {
        "x": 200,
        "y": 200
      },
      "units": "Hz / s"
    },
    {
      "id": "flow-energy-injection",
      "name": "Inertial Response",
      "equation": "Total_Demand - Total_Generation",
      "from_stock": "stock-kinetic-energy",
      "to_stock": null,
      "position": {
        "x": 500,
        "y": 350
      },
      "units": "MW"
    },
    {
      "id": "flow-reserve-deployment",
      "name": "Reserve Deployment",
      "equation": "IF(ABS(Frequency_Deviation) > Deadband, Spinning_Reserve * Droop_Response * Frequency_Deviation / Nominal_Frequency, 0)",
      "from_stock": "stock-reserve",
      "to_stock": null,
      "position": {
        "x": 300,
        "y": 500
      }
    },
    {
      "id": "flow-reserve-restoration",
      "name": "Reserve Restoration",
      "equation": "(Max_Reserve - Spinning_Reserve) / Reserve_Restoration_Time",
      "from_stock": null,
      "to_stock": "stock-reserve",
      "position": {
        "x": 200,
        "y": 400
      }
    }
  ],
  "variables": [
    {
      "id": "var-generation",
      "name": "Total Generation",
      "equation": "Base_Generation + Primary_Response + Secondary_Response",
      "position": {
        "x": 100,
        "y": 100
      },
      "units": "MW"
    },
    {
      "id": "var-demand",
      "name": "Total Demand",
      "equation": "Base_Demand + Demand_Fluctuation",
      "position": {
        "x": 200,
        "y": 100
      },
      "units": "MW"
    },
    {
      "id": "var-base-gen",
      "name": "Base Generation",
      "equation": "1000",
      "position": {
        "x": 100,
        "y": 50
      },
      "units": "MW"
    },
    {
      "id": "var-base-demand",
      "name": "Base Demand",
      "equation": "1000",
      "position": {
        "x": 200,
        "y": 50
      },
      "units": "MW"
    },
    {
      "id": "var-demand-fluct",
      "name": "Demand Fluctuation",
      "equation": "50 * SIN(Time * 0.1)",
      "position": {
        "x": 300,
        "y": 50
      },
      "units": "MW"
    },
    {
      "id": "var-inertia",
      "name": "System Inertia",
      "equation": "5",
      "position": {
        "x": 350,
        "y": 100
      },
      "units": "s"
    },
    {
      "id": "var-nominal",
      "name": "Nominal Frequency",
      "equation": "60",
      "position": {
        "x": 400,
        "y": 100
      },
      "units": "Hz"
    },
    {
      "id": "var-deviation",
      "name": "Frequency Deviation",
      "equation": "Nominal_Frequency - Grid_Frequency",
      "position": {
        "x": 400,
        "y": 200
      },
      "units": "Hz"
    },
    {
      "id": "var-inertia-const",
      "name": "Inertia Constant",
      "equation": "10",
      "position": {
        "x": 500,
        "y": 100
      },
      "units": "s"
    },
    {
      "id": "var-deadband",
      "name": "Deadband",
      "equation": "0.02",
      "position": {
        "x": 250,
        "y": 350
      },
      "units": "Hz"
    },
    {
      "id": "var-droop",
      "name": "Droop Response",
      "equation": "0.05",
      "position": {
        "x": 350,
        "y": 350
      }
    },
    {
      "id": "var-max-reserve",
      "name": "Max Reserve",
      "equation": "1000",
      "position": {
        "x": 150,
        "y": 350
      },
      "units": "MW"
    },
    {
      "id": "var-restoration-time",
      "name": "Reserve Restoration Time",
      "equation": "30",
      "position": {
        "x": 150,
        "y": 450
      },
      "units": "s"
    },
    {
      "id": "var-primary-response",
      "name": "Primary Response",
      "equation": "Droop_Response * Frequency_Deviation * 100",
      "position": {
        "x": 100,
        "y": 150
      },
      "units": "MW"
    },
    {
      "id": "var-secondary-response",
      "name": "Secondary Response",
      "equation": "0",
      "position": {
        "x": 200,
        "y": 150
      },
      "units": "MW"
    }
  ],
  "connectors": [],
  "time_settings": {
    "start": 0,
    "end": 60,
    "dt": 0.01,
    "integration_method": "radau",
    "rtol": 1e-10,
    "atol": 1e-11
  },
  "created_at": "2026-01-12T08:00:00.000000+00:00",
  "updated_at": "2026-01-12T08:00:00.000000+00:00"
}

{
  "id": "traffic-flow-dynamics-soc",
  "name": "Traffic Flow Dynamics Model",
  "description": "Illustrative traffic stock-flow model using a linear speed-density relation and queue heuristics. Lighthill and Whitham (1955), Part II, is conceptual background; this file is not a verified spatial discretization or reproduction of the LWR conservation law. Parameter units, vehicle conservation and numerical stability require review.",
  "stocks": [
    {
      "id": "stock-density",
      "name": "Traffic_Density",
      "initial_value": 20,
      "equation": "",
      "position": {
        "x": 300,
        "y": 100
      }
    },
    {
      "id": "stock-queue",
      "name": "Queue_Length",
      "initial_value": 0,
      "equation": "",
      "position": {
        "x": 500,
        "y": 100
      }
    },
    {
      "id": "stock-throughput",
      "name": "Cumulative_Throughput",
      "initial_value": 0,
      "equation": "",
      "position": {
        "x": 300,
        "y": 250
      }
    }
  ],
  "flows": [
    {
      "id": "flow-inflow",
      "name": "Traffic_Inflow",
      "equation": "Demand * (1 + Peak_Factor * SIN(TIME / 12 * 3.14159))",
      "from_stock": null,
      "to_stock": "stock-density",
      "position": {
        "x": 150,
        "y": 100
      }
    },
    {
      "id": "flow-outflow",
      "name": "Traffic_Outflow",
      "equation": "Flow_Rate",
      "from_stock": "stock-density",
      "to_stock": null,
      "position": {
        "x": 400,
        "y": 100
      }
    },
    {
      "id": "flow-queueform",
      "name": "Queue_Formation",
      "equation": "MAX(0, Traffic_Density - Critical_Density) * Spillback_Rate",
      "from_stock": null,
      "to_stock": "stock-queue",
      "position": {
        "x": 450,
        "y": 50
      }
    },
    {
      "id": "flow-queuediss",
      "name": "Queue_Dissipation",
      "equation": "Queue_Length * Queue_Discharge_Rate * IF(Traffic_Density < Critical_Density, 1, 0.2)",
      "from_stock": "stock-queue",
      "to_stock": null,
      "position": {
        "x": 550,
        "y": 50
      }
    },
    {
      "id": "flow-thruput",
      "name": "Throughput",
      "equation": "Flow_Rate",
      "from_stock": null,
      "to_stock": "stock-throughput",
      "position": {
        "x": 300,
        "y": 175
      }
    }
  ],
  "variables": [
    {
      "id": "var-demand",
      "name": "Demand",
      "equation": "50",
      "position": {
        "x": 100,
        "y": 50
      }
    },
    {
      "id": "var-peakfact",
      "name": "Peak_Factor",
      "equation": "0.4",
      "position": {
        "x": 200,
        "y": 50
      }
    },
    {
      "id": "var-critdens",
      "name": "Critical_Density",
      "equation": "50",
      "position": {
        "x": 400,
        "y": 175
      }
    },
    {
      "id": "var-jamdens",
      "name": "Jam_Density",
      "equation": "150",
      "position": {
        "x": 500,
        "y": 175
      }
    },
    {
      "id": "var-freeflow",
      "name": "Free_Flow_Speed",
      "equation": "60",
      "position": {
        "x": 150,
        "y": 175
      }
    },
    {
      "id": "var-speed",
      "name": "Traffic_Speed",
      "equation": "Free_Flow_Speed * (1 - Traffic_Density / Jam_Density)",
      "position": {
        "x": 250,
        "y": 175
      }
    },
    {
      "id": "var-flowrate",
      "name": "Flow_Rate",
      "equation": "Traffic_Density * Traffic_Speed",
      "position": {
        "x": 350,
        "y": 50
      }
    },
    {
      "id": "var-spillrate",
      "name": "Spillback_Rate",
      "equation": "0.1",
      "position": {
        "x": 400,
        "y": 50
      }
    },
    {
      "id": "var-discharge",
      "name": "Queue_Discharge_Rate",
      "equation": "0.2",
      "position": {
        "x": 550,
        "y": 100
      }
    },
    {
      "id": "var-los",
      "name": "Level_of_Service",
      "equation": "IF(Traffic_Density < 20, 1, IF(Traffic_Density < 35, 2, IF(Traffic_Density < 50, 3, IF(Traffic_Density < 70, 4, IF(Traffic_Density < 100, 5, 6)))))",
      "position": {
        "x": 200,
        "y": 250
      }
    }
  ],
  "connectors": [
    {
      "id": "conn-1",
      "from_element": "Traffic_Density",
      "to_element": "Traffic_Speed"
    }
  ],
  "time_settings": {
    "start": 0,
    "end": 48,
    "dt": 0.25,
    "integration_method": "radau"
  },
  "created_at": "2026-01-12T02:49:51.600040+00:00",
  "updated_at": "2026-01-12T02:49:51.600050+00:00",
  "source": "https://doi.org/10.1098/rspa.1955.0089",
  "reference": "Lighthill, M.J. and Whitham, G.B. (1955). On kinematic waves II. A theory of traffic flow on long crowded roads. Proceedings of the Royal Society A 229(1178):317-345. doi:10.1098/rspa.1955.0089."
}

{
  "id": "milgram-small-world-soc",
  "name": "Milgram Small World Network",
  "description": "Stanley Milgram's 1967 'six degrees of separation' experiment showing social networks have small average path lengths despite large size. Reference: Milgram, S. (1967). The Small World Problem. Psychology Today, 2(1), 60-67. Source: https://doi.org/10.1037/e400002009-005",
  "stocks": [
    {
      "id": "stock-reached",
      "name": "People_Reached",
      "initial_value": 1,
      "equation": "",
      "position": {
        "x": 200,
        "y": 200
      }
    },
    {
      "id": "stock-steps",
      "name": "Chain_Steps",
      "initial_value": 0,
      "equation": "",
      "position": {
        "x": 400,
        "y": 200
      }
    }
  ],
  "flows": [
    {
      "id": "flow-spread",
      "name": "Network_Spread",
      "equation": "People_Reached * branching_factor * (1 - People_Reached / population)",
      "from_stock": null,
      "to_stock": "stock-reached",
      "position": {
        "x": 100,
        "y": 200
      }
    },
    {
      "id": "flow-step",
      "name": "Step_Count",
      "equation": "IF(People_Reached < target_reached, 1, 0)",
      "from_stock": null,
      "to_stock": "stock-steps",
      "position": {
        "x": 400,
        "y": 300
      }
    }
  ],
  "variables": [
    {
      "id": "var-pop",
      "name": "population",
      "equation": "300000000",
      "position": {
        "x": 200,
        "y": 100
      }
    },
    {
      "id": "var-branch",
      "name": "branching_factor",
      "equation": "50",
      "position": {
        "x": 100,
        "y": 100
      }
    },
    {
      "id": "var-target",
      "name": "target_reached",
      "equation": "population * 0.5",
      "position": {
        "x": 300,
        "y": 100
      }
    },
    {
      "id": "var-coverage",
      "name": "Network_Coverage",
      "equation": "People_Reached / population",
      "position": {
        "x": 200,
        "y": 350
      }
    },
    {
      "id": "var-remaining",
      "name": "Steps_Remaining",
      "equation": "ln(population / People_Reached) / ln(branching_factor)",
      "position": {
        "x": 400,
        "y": 350
      }
    },
    {
      "id": "var-avg-path",
      "name": "Avg_Path_Length",
      "equation": "ln(population) / ln(branching_factor)",
      "position": {
        "x": 300,
        "y": 400
      }
    },
    {
      "id": "var-clustering",
      "name": "clustering_coefficient",
      "equation": "0.1",
      "position": {
        "x": 500,
        "y": 100
      }
    }
  ],
  "connectors": [
    {
      "id": "conn-1",
      "from_element": "People_Reached",
      "to_element": "Network_Spread"
    },
    {
      "id": "conn-2",
      "from_element": "branching_factor",
      "to_element": "Network_Spread"
    },
    {
      "id": "conn-3",
      "from_element": "population",
      "to_element": "Network_Coverage"
    }
  ],
  "time_settings": {
    "start": 0,
    "end": 10,
    "dt": 1,
    "integration_method": "radau"
  },
  "source": "https://doi.org/10.1037/h0024480",
  "reference": "Milgram S. The Small World Problem. Psychology Today. 1967;1(1):61-67."
}

{
  "id": "greenshields-traffic-flow-model-tra",
  "name": "Greenshields Traffic Flow Model",
  "description": "Illustrative traffic stock-flow model using the Greenshields linear speed-density relation. Capacity follows from the parabolic flow-density relation. Arrival forcing and queue equations are local illustrative additions, not a reproduction of the 1935 empirical study; parameter calibration and numerical stability remain unverified.",
  "stocks": [
    {
      "id": "s1",
      "name": "Vehicle_Density",
      "initial_value": 20,
      "equation": "",
      "position": {
        "x": 200,
        "y": 200
      }
    },
    {
      "id": "s2",
      "name": "Queue_Length",
      "initial_value": 0,
      "equation": "",
      "position": {
        "x": 400,
        "y": 200
      }
    }
  ],
  "flows": [
    {
      "id": "f1",
      "name": "Density_Change",
      "equation": "(Arrival_Rate - Departure_Rate) / Road_Length",
      "from_stock": null,
      "to_stock": "s1",
      "position": {
        "x": 100,
        "y": 200
      }
    },
    {
      "id": "f2",
      "name": "Queue_Growth",
      "equation": "IF(Vehicle_Density > Jam_Density * 0.8, Arrival_Rate - Capacity, 0)",
      "from_stock": null,
      "to_stock": "s2",
      "position": {
        "x": 500,
        "y": 200
      }
    }
  ],
  "variables": [
    {
      "id": "v1",
      "name": "Free_Flow_Speed",
      "equation": "60",
      "position": {
        "x": 200,
        "y": 50
      }
    },
    {
      "id": "v2",
      "name": "Jam_Density",
      "equation": "150",
      "position": {
        "x": 350,
        "y": 50
      }
    },
    {
      "id": "v3",
      "name": "Road_Length",
      "equation": "1",
      "position": {
        "x": 500,
        "y": 50
      }
    },
    {
      "id": "v4",
      "name": "Arrival_Rate",
      "equation": "1500 + 500 * SIN(TIME * 0.5)",
      "position": {
        "x": 200,
        "y": 100
      }
    },
    {
      "id": "v5",
      "name": "Speed",
      "equation": "Free_Flow_Speed * (1 - Vehicle_Density / Jam_Density)",
      "position": {
        "x": 200,
        "y": 350
      }
    },
    {
      "id": "v6",
      "name": "Flow",
      "equation": "Vehicle_Density * Speed",
      "position": {
        "x": 400,
        "y": 350
      }
    },
    {
      "id": "v7",
      "name": "Capacity",
      "equation": "Free_Flow_Speed * Jam_Density / 4",
      "position": {
        "x": 300,
        "y": 420
      }
    },
    {
      "id": "v8",
      "name": "Departure_Rate",
      "equation": "MIN(Flow, Capacity)",
      "position": {
        "x": 500,
        "y": 420
      }
    },
    {
      "id": "v9",
      "name": "Level_of_Service",
      "equation": "IF(Vehicle_Density < Jam_Density * 0.3, 1, IF(Vehicle_Density < Jam_Density * 0.6, 2, 3))",
      "position": {
        "x": 300,
        "y": 480
      }
    }
  ],
  "connectors": [
    {
      "id": "c1",
      "from_element": "Vehicle_Density",
      "to_element": "Speed"
    }
  ],
  "time_settings": {
    "start": 0,
    "end": 24,
    "dt": 0.1,
    "integration_method": "radau"
  },
  "created_at": "2026-01-15T14:49:43.657712+00:00",
  "updated_at": "2026-01-15T14:49:43.657721+00:00",
  "source": "https://onlinepubs.trb.org/Onlinepubs/hrbproceedings/14/14P1-023.pdf",
  "reference": "Greenshields, B.D. (1935). A Study of Traffic Capacity. Highway Research Board Proceedings 14, Part I:448-477 (including discussion)."
}

{
  "id": "world2-forrester-original-cla",
  "name": "World2 Forrester Original Model",
  "description": "Jay Forrester’s five-sector WORLD2 global dynamics model. Version 1.8 restores the 1970 primary D-1354 documentor (MIT archive PDF pp. 82–91), including its 22 piecewise-linear feedback tables, birth/death normals 0.045/0.025 and initial agricultural fraction 0.3. Existing element IDs and positions are preserved. Capital Generation Multiplier is the source CIPC table divided by the retained 0.05 normal, an algebraically identical rescaling. The documented baseline pre/post-1970 policy coefficients are equal. Explicit Radau integration preserves the 1900–2100 annual output grid. This historical scenario is not a contemporary population or climate calibration.",
  "source": "https://dome.mit.edu/bitstream/handle/1721.3/189645/39080024064039.pdf?isAllowed=y&sequence=1",
  "reference": "Forrester, J.W. (1970), WORLD2 D-1354 equation documentor, equations 1–43, MIT archive PDF pp. 82–91; explicitly the 1970 formulation, not the later 1973 book variant.",
  "stocks": [
    {
      "id": "stock-pop",
      "name": "Population",
      "initial_value": 1650000000,
      "equation": "",
      "position": {
        "x": 100,
        "y": 200
      }
    },
    {
      "id": "stock-capital",
      "name": "Capital Investment",
      "initial_value": 400000000,
      "equation": "",
      "position": {
        "x": 300,
        "y": 200
      }
    },
    {
      "id": "stock-resources",
      "name": "Natural Resources",
      "initial_value": 900000000000,
      "equation": "",
      "position": {
        "x": 500,
        "y": 200
      }
    },
    {
      "id": "stock-pollution",
      "name": "Pollution",
      "initial_value": 200000000,
      "equation": "",
      "position": {
        "x": 300,
        "y": 350
      }
    },
    {
      "id": "stock-agric-frac",
      "name": "Capital in Agriculture Fraction",
      "initial_value": 0.3,
      "equation": "",
      "position": {
        "x": 100,
        "y": 350
      }
    }
  ],
  "flows": [
    {
      "id": "flow-births",
      "name": "Birth Rate",
      "equation": "Population * Birth_Rate_Normal * Birth_Rate_Multiplier",
      "from_stock": null,
      "to_stock": "stock-pop",
      "position": {
        "x": 50,
        "y": 200
      }
    },
    {
      "id": "flow-deaths",
      "name": "Death Rate",
      "equation": "Population * Death_Rate_Normal * Death_Rate_Multiplier",
      "from_stock": "stock-pop",
      "to_stock": null,
      "position": {
        "x": 150,
        "y": 200
      }
    },
    {
      "id": "flow-capital-gen",
      "name": "Capital Generation",
      "equation": "Population * Capital_Generation_Normal * Capital_Generation_Multiplier",
      "from_stock": null,
      "to_stock": "stock-capital",
      "position": {
        "x": 250,
        "y": 200
      }
    },
    {
      "id": "flow-depreciation",
      "name": "Capital Depreciation",
      "equation": "Capital_Investment / Capital_Normal_Lifetime",
      "from_stock": "stock-capital",
      "to_stock": null,
      "position": {
        "x": 350,
        "y": 200
      }
